"""SELECTs recuperados do chat Sansaude, sem dependencia de PHP."""
QUERIES = {'beneficiariosPorCpf': "select v1.cd_matricula, v1.ds_plano, v1.nm_responsavel_financeiro\n               from dbamv.vdic_auto_agenda_san_001 v1\n              where lpad(v1.nr_cpf, 11, '0') = :cpf\n              order by v1.ds_plano", 'beneficiario': 'select v1.cd_matricula, v1.nm_segurado, v1.cd_plano, v1.ds_plano, v1.cd_paciente_mv, v1.elegibilidade, v1.idade\n               from dbamv.vdic_auto_agenda_san_001 v1\n              where v1.cd_matricula = :mat', 'consultarEspecialidades': 'select distinct v4.cd_especialid, v4.ds_especialid, v4.idade_de, v4.idade_ate\n               from dbamv.vdic_auto_agenda_san_004 v4', 'prestadores': 'select distinct v4.cd_prestador, v4.nm_prestador\n               from dbamv.vdic_auto_agenda_san_004 v4\n              where v4.cd_especialid = :esp\n                and :idade between v4.idade_de and v4.idade_ate\n              order by 2', 'proximaConsulta': "select to_char(max(x.dt_proxima_consulta), 'DD/MM/YYYY') dt_proxima_consulta,\n                    case when max(x.dt_proxima_consulta) > sysdate + 1 then 1 else 0 end retorno\n               from (select v2.dt_emissao, min(nvl(v6.dt_agenda, v2.dt_proxima_consulta)) dt_proxima_consulta,\n                            v2.cd_especialidade_mv, v2.cd_prestador_mv, v2.cd_matricula\n                       from dbamv.vdic_auto_agenda_san_002 v2,\n                            (select * from dbamv.vdic_auto_agenda_san_006 v6\n                              where v6.cd_atendimento is not null\n                                and v6.cd_tip_mar = 2\n                                and v6.cd_paciente = :pac) v6\n                      where v2.cd_matricula = :mat\n                        and v2.cd_especialidade_mv = :esp\n                        and v2.cd_prestador_mv = :prest\n                        and v2.cd_especialidade_mv = v6.cd_especialid(+)\n                        and v2.cd_prestador_mv = v6.cd_prestador(+)\n                      group by v2.dt_emissao, v2.cd_especialidade_mv, v2.cd_prestador_mv, v2.cd_matricula) x", 'horarios': "select * from (\n                select v3.cd_agenda_central, v3.cd_it_agenda_central, v3.cd_unidade_atendimento, v3.cd_setor,\n                       v3.cd_item_agendamento, v3.cd_especialid, v3.ds_especialid, v3.cd_prestador, v3.nm_prestador,\n                       v3.cd_servico, v3.cd_tip_mar, v3.ds_tip_mar, v3.hr_agenda, v3.tempo_consulta,\n                       to_char(v3.dh_agenda, 'DD/MM/YYYY HH24:MI:SS') dh_agenda,\n                       row_number() over (partition by v3.cd_escala_central, v3.cd_tip_mar\n                                          order by v3.dh_agenda, v3.cd_it_agenda_central) rn\n                  from dbamv.vdic_auto_agenda_san_003 v3\n                 where trunc(v3.dt_agenda) = to_date(:data, 'DD/MM/YYYY')\n                   and v3.cd_tip_mar = :tip\n                   and v3.cd_prestador = :prest\n                   and v3.cd_especialid = :esp\n                   and v3.qt_agenda_tm > v3.qt_agendados_tm\n             )\n             where rn <= 3\n             order by hr_agenda", 'agendamentoExistente': "select to_char(v6.dh_agenda, 'DD/MM/YYYY HH24:MI:SS') dh_agenda, v6.nm_prestador\n               from dbamv.vdic_auto_agenda_san_006 v6\n              where v6.cd_especialid = :esp\n                and v6.cd_paciente = :pac\n                and v6.dh_agenda >= sysdate\n              order by v6.dh_agenda", 'agendamentosFuturos': "select * from (\n                select v6.*, to_char(v6.dh_agenda, 'DD/MM/YYYY HH24:MI:SS') dh_agenda_txt\n                  from dbamv.vdic_auto_agenda_san_006 v6\n                 where v6.cd_paciente = :pac\n                   and v6.dh_agenda >= sysdate\n                 order by v6.dh_agenda\n             ) where rownum <= 20", 'agendamentoConfirmado': "select count(*) qtd\n               from dbamv.vdic_auto_agenda_san_005 v5\n              where v5.cd_paciente = :pac\n                and v5.cd_prestador = :prest\n                and v5.dh_agenda = to_date(:dh, 'DD/MM/YYYY HH24:MI:SS')"}
